const D = { energy: .6, scale: 1, density: .5, speed: 1, sweep: .5, hue: 210, x: .5, y: .68, style: 'pewter', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- A pipe-organ facade: ranks of graduated metal flue pipes in a carved case, an unseen
// light raking across the rank so the burnished pipes gleam in turn. A SET: it stands as a
// centred instrument and leaves margins open; alpha scales every mark. Not industrial
// pipework (set.pipework), not a piano (set.piano). ----

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height), sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, en = cl(P.energy,0,1), dn = cl(P.density,0,1), swp = cl(P.sweep,0,1);
const HU = ((P.hue%360)+360)%360, tt = K.t;
const bp = sty==='blueprint', gilt = sty==='gilt', dk = sty==='chiaroscuro', eng = sty==='engraving';
const AL = cl(P.alpha,0,100);
if (AL > 0.5) {

const bass = (S.b = (S.b||0)*.84 + (A.bass||0)*.16);
const light = (.5+.5*en)*(.55+.5*K.intensity) + bass*.22;
// the raking light azimuth drifts (incommensurate) -> a bright zone sweeps the rank
const az = 0.8*Math.sin(tt*.09*swp*P.speed) + 0.35*Math.sin(tt*.017*P.speed+1.2) + 0.2*Math.sin(tt*.23*swp+2.0);

// metal ramp: v 0 shadow .. 1 hot specular
function metal(v){
  if (bp)   return [196,60,cl(14+v*12,8,32)];
  if (eng)  return [34,6,cl(8+v*88,5,97)];
  if (gilt) return [cl(44-v*8,0,60),cl(70-v*40,10,80),cl(24+v*70,8,98)];
  if (dk)   return [HU,cl(10-v*8,0,14),cl(2+v*92,1,96)];
  return [cl(HU-6+v*10,0,360),cl(12-v*8,2,18),cl(22+v*66,6,96)];    // tin/pewter
}
function wood(v){ if (bp) return [200,50,cl(10+v*8,6,26)]; if (eng) return [34,8,cl(12+v*40,6,60)];
  return [cl(28,0,60),cl(gilt?54:40,10,66),cl(8+v*30,4,46)]; }
function setF(c,a){ fill(c[0],c[1],c[2],a*AL/100); }
function setS(c,a){ stroke(c[0],c[1],c[2],a*AL/100); }

const cx = cl(P.x,.08,.92)*width;
const footY = cl(P.y,.4,.9)*height;
const sc = cl(P.scale,.3,2.4);
const pw = u*.017*sc;                                     // pipe width
const NP = 12 + Math.round(dn*16);                        // number of facade pipes
const gap = pw*0.12;
const totalW = NP*(pw+gap);
const x0 = cx - totalW*0.5;
const maxH = u*.52*sc;
// tower profile: a few gaussian peaks -> the classic organ silhouette (towers + flats)
const towers = [[0.5,1.0,0.14],[0.16,0.72,0.10],[0.84,0.72,0.10],[0.33,0.5,0.09],[0.67,0.5,0.09]];
function heightAt(q){ let h=0.24; for(const T of towers){ h += T[1]*Math.exp(-Math.pow((q-T[0])/T[2],2)); } return cl(h,0.2,1.35); }
const brightC = 0.5 + az*0.5;                             // bright-zone centre in q-space

push();
// ---- carved wooden plinth the pipes stand on ----
const plH = u*.06*sc;
setF(wood(.5*light+.2), 92);
rect(x0-pw*.8, footY, totalW+pw*1.6, plH, pw*.2);
// plinth mouldings + grain
setS(wood(.9*light+.3), 40); strokeWeight(Math.max(1,u*.0011));
line(x0-pw*.8, footY+plH*.28, x0+totalW+pw*.8, footY+plH*.28);
setS(wood(.2), 30);
for(let gx=0;gx<10;gx++){ const wx=x0+totalW*(gx/9); line(wx,footY+plH*.4,wx+pw*.3,footY+plH*.95); }

// ---- the pipes (draw as shaded vertical cylinders; a bright zone sweeps across) ----
const NPX = 6;
for (let i=0;i<NP;i++){
  const q=(i+.5)/NP;
  const hh = heightAt(q)*maxH*(0.85+0.25*fr(i*3.1));
  const px = x0 + i*(pw+gap) + gap*.5;
  const topY = footY - hh;
  const facing = Math.exp(-Math.pow((q-brightC)/0.28,2));  // how directly this pipe faces the light
  const pipeLum = (0.34 + facing*0.62)*light;
  const hxOff = az*pw*0.55;                                 // specular line shifts with the light
  // cylinder body: vertical slivers shaded by angle from the highlight
  for (let s2=0;s2<NPX;s2++){
    const fx0 = -0.5 + s2/NPX, fx1 = -0.5 + (s2+1)/NPX, fxm=(fx0+fx1)*.5;
    const ang = (fxm*pw - hxOff)/(pw*0.5);                  // -1..1 across the pipe
    const cyl = cl(Math.cos(ang*1.35), 0, 1);              // Lambert-ish across the round body
    const v = cl(pipeLum*(0.35+0.75*cyl), 0, 1.1);
    setF(metal(v), (dk?86:90));
    if (bp||eng){ noStroke(); }
    noStroke();
    rect(px + (fxm+0.5-1/(2*NPX))*pw, topY, pw/NPX+0.6, hh);
  }
  // rounded top + dark mouth (flue) + languid line (texture detail)
  setF(metal(cl(pipeLum*0.7,0,1)), 90); noStroke();
  ellipse(px+pw*.5, topY, pw*1.02, pw*.7);
  setF(metal(cl(0.6+pipeLum*.5,0,1)), 80);
  ellipse(px+pw*.5+hxOff*.6, topY, pw*.4, pw*.4);           // top gleam
  // mouth
  const mY = footY - hh*0.10;
  setF(metal(0.03), 80);
  rect(px+pw*.22, mY-pw*.5, pw*.56, pw*.55, pw*.1);
  setS(metal(cl(0.4+pipeLum*.4,0,1)), 60); strokeWeight(Math.max(1,u*.0009));
  line(px+pw*.22, mY-pw*.5, px+pw*.78, mY-pw*.5);          // languid highlight
  // vertical seam highlight down the round of the pipe
  if (!bp){ setS(metal(cl(0.5+pipeLum*.6,0,1)), 55*facing); strokeWeight(Math.max(1,u*.0012));
    line(px+pw*.5+hxOff, topY+pw*.3, px+pw*.5+hxOff, footY-pw*.2); }
  // rim outline
  if (bp||eng){ noFill(); setS(metal(cl(pipeLum,0,1)),70); strokeWeight(Math.max(1,u*.001));
    rect(px, topY, pw, hh); }
}

// ---- carved pipe-shades (tracery) over the tower tops + side pilasters ----
setS(wood(.7*light+.2), 55); strokeWeight(Math.max(1,u*.0016)); noFill();
for (const T of towers){
  const q=T[0]; const px=x0+q*totalW; const hh=heightAt(q)*maxH; const ty=footY-hh;
  for(let a=0;a<5;a++){ const off=(a-2)*pw*.9;
    arc(px+off, ty-pw*.2, pw*1.7, pw*1.7, Math.PI, Math.PI*2); }
}
// side pilasters framing the case (keeps margins, reads as an instrument not a wall)
setF(wood(.45*light+.15), 90); noStroke();
rect(x0-pw*1.3, footY-maxH*.72, pw*.9, maxH*.72+plH*.2, pw*.15);
rect(x0+totalW+pw*.4, footY-maxH*.72, pw*.9, maxH*.72+plH*.2, pw*.15);

pop();
blendMode(BLEND); noTint(); drawingContext.shadowBlur=0; strokeWeight(1);
}
